"""Create an explicitly unrouted PCB placement study, preserving the source board."""
from pathlib import Path
import wx,pcbnew,json,hashlib,argparse
parser=argparse.ArgumentParser();parser.add_argument("--distinct-index",type=int);args=parser.parse_args()
app=wx.App(False);O=Path(__file__).resolve().parent;root=O.parents[1];src=root/'hardware/xe-minimal/fixed-usb-limit-trial/ncu-sensor-trial/pendant-xe-minimal.kicad_pcb';review=O/'film-lap-pad-reroute-locations-review.json';r=json.loads(review.read_text());assert hashlib.sha256(src.read_bytes()).hexdigest()==r['pcb_sha256'];pair=r['best_pairs'][0] if args.distinct_index is None else r['distinct_signal_pad_pairs'][args.distinct_index];b=pcbnew.LoadBoard(str(src));old=next(f for f in b.GetFootprints()if f.GetReference()=='TH1');b.Remove(old)
f=pcbnew.FOOTPRINT(b);f.SetReference('TH1');f.SetValue('103JT-025 external - UNROUTED STUDY');f.SetLayer(pcbnew.B_Cu);f.SetPosition(pcbnew.VECTOR2I(0,0));f.SetAttributes(pcbnew.FP_SMD);b.Add(f)
ls=pcbnew.LSET();ls.AddLayer(pcbnew.B_Cu);ls.AddLayer(pcbnew.B_Mask)
for spec in pair['pads']:
 q=pcbnew.PAD(f);q.SetNumber('1'if spec['net']=='/BAT_TS'else'2');q.SetAttribute(pcbnew.PAD_ATTRIB_SMD);q.SetShape(pcbnew.PAD_SHAPE_RECT);q.SetLayerSet(ls);q.SetSize(pcbnew.VECTOR2I(*(pcbnew.FromMM(x)for x in spec['size_mm'])));q.SetPosition(pcbnew.VECTOR2I(*(pcbnew.FromMM(x)for x in spec['pcb_center_mm'])));q.SetNet(b.FindNet(spec['net']));f.Add(q)
d=root/('hardware/xe-minimal/film-lap-pad-placement-study'+(''if args.distinct_index is None else '-'+str(args.distinct_index)));d.mkdir(exist_ok=True);out=d/'pendant-xe-film-lap-unrouted.kicad_pcb';pcbnew.SaveBoard(str(out),b)
check=pcbnew.LoadBoard(str(out));fp=next(f for f in check.GetFootprints()if f.GetReference()=='TH1');assert len(list(fp.Pads()))==2
j={'status':'UNROUTED_PLACEMENT_STUDY_DO_NOT_MANUFACTURE','release_allowed':False,'source_pcb_sha256':r['pcb_sha256'],'candidate_pcb_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'distinct_pair_index':args.distinct_index,'selected_pair':pair,'track_segments_requiring_review':sorted({t['uuid']for p in pair['pads']for t in p['tracks_to_reroute']}),'limits':['Known copper conflicts remain; no routing removed or repaired.','No schematic, BOM or approved thermistor circuit substitution.','Old TH1 footprint replaced by dedicated wire pads; route endpoints may no longer connect.','No DRC, outline, mask, mechanical access or strain-relief acceptance.','Source board remains unchanged.']};(d/'review.json').write_text(json.dumps(j,indent=2)+'\n');print(str(out));print([(p.GetNumber(),p.GetNetname(),pcbnew.ToMM(p.GetPosition().x),pcbnew.ToMM(p.GetPosition().y))for p in fp.Pads()])
